//! Postcapture descriptions; no new performance gate or prover execution.
#[path="/tmp/zopro-ready-arithmetic/observations.rs"]mod observations;
use observations::median;use serde_json::{json,Value};use std::{fs,path::Path,collections::BTreeMap};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new("/tmp/zopro-ready-c7a");let data=r.join("remote-results/output/measure/performance");let config=read(r.join("remote-results/output/measure/config.json"));let rows=read(data.join("rows.json"));let mut cases=BTreeMap::new();for c in config["cases"].as_array().unwrap(){if c["shape"]!="1x2"{continue;}let name=c["name"].as_str().unwrap();let mut outside=Vec::new();let mut fill_shares=Vec::new();let mut after_fill=Vec::new();let mut kinds=BTreeMap::<u64,Vec<Value>>::new();
 for row in rows.as_array().unwrap().iter().filter(|row|row["case"]==name&&row["variant"]=="on"&&row["phase"]=="latency"){let path=data.join(format!("latency/b{}/{name}/on/proofs/transfer_confidential_1_2/readiness.json",row["block"].as_u64().unwrap()));let snapshots=read(path);for (i,snapshot)in snapshots.as_array().unwrap().iter().enumerate(){let events:Vec<_>=snapshot["events"].as_array().unwrap().iter().filter(|e|e["state"]==2).collect();let lo=events.iter().map(|e|e["ready"].as_u64().unwrap()).min().unwrap();let hi=events.iter().map(|e|e["end"].as_u64().unwrap()).max().unwrap();let span=(hi-lo)as f64/1e6;let request=row["samples_ms"][i].as_f64().unwrap();assert!(span<=request);outside.push(request-span);let mut total=0u64;let mut fill=0u64;let mut fill_end=0u64;let mut groups=BTreeMap::<u64,Vec<&Value>>::new();for e in events{let k=e["kind"].as_u64().unwrap();let elapsed=e["end"].as_u64().unwrap()-e["start"].as_u64().unwrap();total+=elapsed;if k<=3{fill+=elapsed;fill_end=fill_end.max(e["end"].as_u64().unwrap());}groups.entry(k).or_default().push(e);}fill_shares.push(fill as f64/total as f64);after_fill.push((hi-fill_end)as f64/1e6);
 for(k,es)in groups{let earliest=es.iter().map(|e|e["ready"].as_u64().unwrap()).min().unwrap();let latest=es.iter().map(|e|e["end"].as_u64().unwrap()).max().unwrap();kinds.entry(k).or_default().push(json!({"units":es.len(),"ready_offset_ms":(earliest-lo)as f64/1e6,"last_end_offset_ms":(latest-lo)as f64/1e6,"median_body_us":median(es.iter().map(|e|(e["end"].as_u64().unwrap()-e["start"].as_u64().unwrap())as f64/1e3).collect()),"median_ready_delay_us":median(es.iter().map(|e|(e["start"].as_u64().unwrap()-e["ready"].as_u64().unwrap())as f64/1e3).collect())}));}
 }}let mut summary=BTreeMap::new();for(k,values)in kinds{let mut m=BTreeMap::new();for key in["units","ready_offset_ms","last_end_offset_ms","median_body_us","median_ready_delay_us"]{m.insert(key,median(values.iter().map(|v|v[key].as_f64().unwrap()).collect()));}summary.insert(k,m);}cases.insert(name,json!({"SDK_time_outside_recorded_arithmetic_interval_ms":median(outside),"fill_share_of_recorded_leaf_elapsed":median(fill_shares),"last_leaf_after_last_fill_ms":median(after_fill),"kinds":summary}));}
 fs::write(r.join("geometry.json"),serde_json::to_vec_pretty(&json!({"scope":"Description of captured current primary proof. Outside-interval time includes both prefix and suffix; it is not an exclusive solver cost. Active leaf intervals include OS descheduling/memory stalls. No causal CPU-time or complete-DAG claim.","cases":cases})).unwrap()).unwrap();println!("Captured primary geometry summarized with per-request outside-interval pairing");}
